// Generated by Claude

// ===== Pixel mačka: dáta a skladanie snímok =====
// Každý znak = jeden pixel. '.' = priehľadné. Farby v PALETTE.
export const PALETTE = {
  o: '#2a2422', // obrys
  G: '#9a8f80', // srsť
  D: '#564c42', // mourovaté pruhy
  W: '#ece4d6', // svetlá papuľka / hruď
  P: '#e8949e', // ružová (uši, nos, jazyk)
  E: '#9ccc5a', // oči
  K: '#1d1a18', // zrenička
  B: '#f0a7a7', // líčka
  R: '#c94a3f', // miska
  r: '#8f2e27', // tieň misky
  F: '#c08a45', // granule
  f: '#7d5527', // granule tmavé
  H: '#e5475b', // srdiečko
  h: '#ff9aa6', // odlesk srdiečka
};

const HEAD = [
  "..oo..........oo..",
  ".oPGo........oGPo.",
  ".oPPGo......oGPPo.",
  ".oGGGGoooooooGGGGo",
  "oGGDGDGGDGGDGDGGGo",
  "oGGGDGGGDDGGGDGGGo",
  "oGGGEEEGGGGEEEGGGo",
  "oDGGEKEGGGGEKEGGDo",
  "oGGGEEEGGGGEEEGGGo",
  "oDGGGGWWPPWWGGGGDo",
  "oGGGGWWoWWoWWGGGGo",
  ".oGGGGWWooWWGGGGo.",
  "..ooGGGGGGGGGGoo..",
  "....oooooooooo....",
];

const EYES = {
  blink: { 6: "oGGGGGGGGGGGGGGGGo", 7: "oDGGoooGGGGoooGGDo", 8: "oGGGGGGGGGGGGGGGGo" },
  happy: { 6: "oGGGGoGGGGGGoGGGGo", 7: "oDGGoGoGGGGoGoGGDo", 8: "oGBBGGGGGGGGGGBBGo" },
};
const MOUTH_OPEN = { 10: "oGGGGWWooooWWGGGGo", 11: ".oGGGGWoPPoWGGGGo." };

function head(eyes = 'open', mouthOpen = false) {
  return HEAD.map((row, i) =>
    (mouthOpen && MOUTH_OPEN[i]) || (EYES[eyes] && EYES[eyes][i]) || row);
}

const BODY = [
  "...oGGGGWWWWGGGGo...",
  "..oGDGGWWWWWWGGDGo..",
  ".oGGDGGWWWWWWGGDGGo.",
  ".oGDGGGWWWWWWGGGDGo.",
  "oGGDGGGWWWWWWGGGDGGo",
  "oGDGGGGWWWWWWGGGGDGo",
  "oGGDGGGWWWWWWGGGDGGo",
  "oGGGDGGWWWWWWGGDGGGo",
  "oGGGGoWWWooWWWoGGGGo",
  "oGGGoWWWWooWWWWoGGGo",
  ".oooooooooooooooooo.",
];

const TAIL = [
  ["......oo", ".....oGo", ".....oDo", ".....oGo", "oo...oDo", "GDoooGGo", "GGDGDGo.", "ooooooo."],
  ["........", "......oo", ".....oGo", "....oDGo", "oo..oGDo", "GDooGDo.", "GGDGGo..", "oooooo.."],
];

const BOWL = ["...oooooo...", ".ooFfFFfFoo.", "oRRRRRRRRRRo", ".oRrRRRRrRo.", "..oooooooo.."];
const HEART = [".oo.oo.", "oHhoHHo", "oHHHHHo", ".oHHHo.", "..oHo..", "...o..."];

export const WIDTH = 32;
export const HEIGHT = 27;

// Poskladá vrstvy [mriežka, x, y] do jednej snímky. Neskoršie vrstvy kreslia navrch.
function compose(layers) {
  const px = Array.from({ length: HEIGHT }, () => Array(WIDTH).fill('.'));
  for (const [grid, x0, y0] of layers) {
    grid.forEach((row, y) => [...row].forEach((c, x) => {
      const X = x0 + x, Y = y0 + y;
      if (c !== '.' && X >= 0 && X < WIDTH && Y >= 0 && Y < HEIGHT) px[Y][X] = c;
    }));
  }
  return px.map(r => r.join(''));
}

const idle   = (t, blink) => compose([[TAIL[t], 24, 17], [BODY, 6, 14], [head(blink ? 'blink' : 'open'), 7, 2]]);
const eating = (t, chew)  => compose([[TAIL[t], 24, 17], [BODY, 6, 14], [head('blink', chew), 7, 7], [BOWL, 10, 22]]);
const petted = (t, hy)    => compose([[TAIL[t], 24, 17], [BODY, 6, 14], [head('happy'), 7, 3], [HEART, 1, hy], [HEART, 24, hy + 2]]);

// Animácie: zoznam snímok pre každý stav
export const ANIMATIONS = {
  idle:   [idle(0), idle(0), idle(1), idle(1), idle(0), idle(0, true), idle(1), idle(1)],
  eating: [eating(0, true), eating(0), eating(1, true), eating(1)],
  petted: [petted(0, 6), petted(1, 4), petted(0, 2), petted(1, 0)],
};

// Vykreslí jednu snímku na canvas (1 pixel mačky = scale × scale pixelov obrazovky)
export function drawFrame(ctx, frame, scale) {
  ctx.clearRect(0, 0, WIDTH * scale, HEIGHT * scale);
  frame.forEach((row, y) => [...row].forEach((c, x) => {
    if (c === '.') return;
    ctx.fillStyle = PALETTE[c];
    ctx.fillRect(x * scale, y * scale, scale, scale);
  }));
}
